mapper.select:
SELECT a.*, b.budget_name, s.subject_name, i.item_name
FROM budget_adjustment a
LEFT JOIN budget b ON a.budget_id = b.budget_id
LEFT JOIN budget_subject s ON a.subject_id = s.subject_id
LEFT JOIN budget_item i ON a.item_id = i.item_id
WHERE 1=1

    AND a.adjustment_type = #{params.adjustmentType}


    AND a.subject_id = #{params.subjectId}


    AND a.item_id = #{params.itemId}


    AND a.adjustment_no LIKE CONCAT('%', #{params.adjustmentNo}, '%')

ORDER BY a.create_time DESC, a.adjustment_no
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM budget_adjustment a
WHERE 1=1

    AND a.adjustment_type = #{params.adjustmentType}


    AND a.subject_id = #{params.subjectId}


    AND a.item_id = #{params.itemId}


    AND a.adjustment_no LIKE CONCAT('%', #{params.adjustmentNo}, '%')

mapper.update:
UPDATE budget_adjustment
adjustment_amount = #{adjustmentAmount}, adjusted_amount = #{adjustedAmount}, adjustment_reason = #{adjustmentReason}, update_time = #{updateTime},
WHERE adjustment_id = #{adjustmentId}
